import{_ as e,o,c as s,ag as r}from"./chunks/framework.wGDfT7ie.js";const h=JSON.parse('{"title":"What is zkde.fi?","description":"","frontmatter":{},"headers":[],"relativePath":"intro.md","filePath":"intro.md"}'),a={name:"intro.md"};function i(n,t,l,d,c,u){return o(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="what-is-zkde-fi" tabindex="-1">What is zkde.fi? <a class="header-anchor" href="#what-is-zkde-fi" aria-label="Permalink to &quot;What is zkde.fi?&quot;">​</a></h1><p><strong>zkde.fi</strong> (by Obsqra Labs) is the first <strong>GATE-compatible</strong> app: a privacy-preserving autonomous agent for DeFi on Starknet, built on <strong>zkDE (Zero-Knowledge Deterministic Engine)</strong> and <strong>GATE (Governed Autonomous Trustless Execution)</strong>. It combines:</p><ul><li><strong>zkML-gated decisions</strong> — Two privacy-preserving ML models (risk score, anomaly detection) gate agent actions. Model outputs stay private; only compliance is public.</li><li><strong>Proof-gated execution</strong> — Every action requires both zkML proofs (Garaga) and execution proofs (Integrity). No proof, no execution.</li><li><strong>Session keys</strong> — Delegate to the agent via Starknet&#39;s native account abstraction. Agent acts within your constraints (max position, protocols, duration).</li><li><strong>Intent commitments</strong> — Replay-safe and fork-safe execution. Each commitment is single-use.</li><li><strong>Selective disclosure</strong> — Prove statements (e.g. &quot;my agent followed the rules&quot; or &quot;yield above X&quot;) without revealing your full strategy or history.</li><li><strong>Confidential positions</strong> — Private transfers use commitments: amounts and balances stay off the public ledger. On Sepolia we use Garaga (Groth16 verifier); on mainnet the stack can use MIST.cash.</li></ul><p>The app is <strong>open source</strong> and lives at <a href="https://zkde.fi" target="_blank" rel="noreferrer">zkde.fi</a>. You connect your Starknet wallet (e.g. ArgentX, Braavos), set constraints (max position, allowed protocols), and grant session keys for autonomous execution.</p><h2 id="hybrid-proof-system" tabindex="-1">Hybrid Proof System <a class="header-anchor" href="#hybrid-proof-system" aria-label="Permalink to &quot;Hybrid Proof System&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Proof System</th><th>Purpose</th></tr></thead><tbody><tr><td>Privacy</td><td>Garaga (Groth16/SNARK)</td><td>zkML proofs, confidential transfers</td></tr><tr><td>Execution</td><td>Integrity (STARK)</td><td>Constraint proofs, receipts</td></tr></tbody></table><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>zkML risk score</strong> — Proves portfolio risk &lt;= threshold without revealing actual score</li><li><strong>zkML anomaly detection</strong> — Proves pool is safe without revealing analysis</li><li><strong>Session keys</strong> — Delegated execution with constraints</li><li><strong>Intent commitments</strong> — Replay-safe execution</li><li><strong>Constraint receipts</strong> — On-chain audit trail</li><li><strong>Compliance profiles</strong> — Productized selective disclosure</li><li><strong>Private deposits/withdrawals</strong> — Amounts hidden</li></ul><p>Next: <a href="/docs/why.html">Why it matters</a> | <a href="/docs/zkml-models.html">zkML Models</a> | <a href="/docs/session-keys.html">Session Keys</a></p>',9)])])}const f=e(a,[["render",i]]);export{h as __pageData,f as default};
